mapper.select:
SELECT b.*, m.*, COUNT(bl.board_like_id) as bln, COUNT(c.comment_id) as cn
FROM board as b LEFT JOIN member as m ON b.member_id = m.member_id
LEFT JOIN board_like as bl ON b.board_id = bl.board_id
LEFT JOIN comment as c ON b.board_id = c.board_id

    WHERE b.board_type = #{boardType}

GROUP BY b.board_id
ORDER BY b.created_at DESC

    LIMIT #{pageSize}


    OFFSET #{offset}

SELECT COUNT(*)
FROM board as b

    WHERE b.board_type = #{boardType}
